  appearance?: NumberInputVariants["appearance"];
  size?: NumberInputVariants["size"];
  wide?: boolean;
}

export interface BaseRadioInputProps extends BaseInputProps<string | number> {
  type: "radio";
  options: Options;
  color?: RadioVariants["color"];
  size?: RadioVariants["size"];
}

export interface BaseSelectInputProps extends BaseInputProps<string | number | (string | number)[]> {
  options: Options;
  multiple?: boolean;
  color?: SelectVariants["color"];
  appearance?: SelectVariants["appearance"];
  size?: SelectVariants["size"];
  wide?: boolean;
}


type CheckboxInputProps = BaseCheckboxInputProps & {
  type: "checkbox";
  options?: never;
};

type NumberInputProps = BaseNumberInputProps & {
  type: "number";
  options?: never;
};
type SelectInputProps = BaseSelectInputProps & {
  type: "select";
};
type RadioInputProps = BaseRadioInputProps & {
  type: "radio";
};
type TextareaProps = BaseTextareaProps & {
  type: "textarea";
  options?: never;
};

// ToDo: change this control to be jujst wrapper for all inputs, not a combined input component
interface CustomInputProps {
  type?: never
  inputClass?: never
  class?: string
}

type CombinedInputProps = FormControlProps &
  (
    | BaseTextInputProps
    | NumberInputProps
    | SelectInputProps
    | CheckboxInputProps
    | RadioInputProps
    | TextareaProps
    | CustomInputProps
  );

type InputProps = CombinedInputProps & {
  labelProps?: Omit<LabelProps, "name" | "required">;
};

defineOptions({
  inheritAttrs: false,
});

const props = withDefaults(defineProps<InputProps>(), {
  options: () => [] as Options,
  wide: true,
});

const model = defineModel<Value>();

const isTextLike = computed(() => !!props.type && ["text", "password", "email", "tel"].includes(props.type));
const isTextarea = computed(() => props.type === "textarea");
const isNumber = computed(() => props.type === "number");
const isSelect = computed(() => props.type === "select");
const isCheckbox = computed(() => props.type === "checkbox");
const isRadio = computed(() => props.type === "radio");
